SELECT p.gender, CAST(p.anchor_age AS INT) AS age, i.careunit, s.los, t.comorbidity_tertile, COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate, COUNT(DISTINCT CASE WHEN l.itemid = '19757-3' THEN l.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS ckd_prevalence, COUNT(DISTINCT CASE WHEN l.itemid = '19758-3' THEN l.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS diabetes_prevalence FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN stayevents s ON a.stay_id = s.stay_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id JOIN transfers t ON a.subject_id = t.subject_id AND a.hadm_id = t.hadm_id WHERE p.gender = 'M' AND CAST(p.anchor_age AS INT) BETWEEN 52 AND 62 AND s.eventtype = 'death' AND (i.careunit = 'ICU' OR i.careunit = 'Non-ICU') AND (s.los <= 5 OR s.los > 5) AND (t.comorbidity_tertile = 'Low' OR t.comorbidity_tertile = 'Medium' OR t.comorbidity_tertile = 'High') AND l.itemid IN ('19757-3', '19758-3') GROUP BY p.gender, age, i.careunit, s.los, t.comorbidity_tertile;